func (this *CodeGenerator) addIdentifier(identifier string) {
	this.cc.addIdentifier(CodeGenerator_identifierEscape(identifier))
}

func (this *CodeGenerator) addGetpropIdentifier(getprop Node) {
	this.cc.startSourceMapping(getprop)
	this.addIdentifier(getprop.getString())
	this.cc.endSourceMapping(getprop)
}

func (this *CodeGenerator) precedence(n Node) int32 {
	if n.isCast() {
		return this.precedence(n.getFirstChild())
	}
	return NodeUtil_precedence(n.getToken())
}

func (this *CodeGenerator) addInvocationTarget(node Node, context CodeGenerator_Context) {
	var first Node = node.getFirstChild()
	var needsParens bool = NodeUtil_isOptChainNode(first)
	if CodeGenerator_isIndirectEval(first) || (node.getBooleanProp(Node_FREE_CALL) && NodeUtil_isNormalOrOptChainGet(first)) {
		this.add("(0,")
		this.addExpr(first, NodeUtil_precedence(Token_rhino_COMMA), CodeGenerator_Context_OTHER)
		this.add(")")
	} else {
		if needsParens {
			this.add("(")
		}
		this.addExpr(first, NodeUtil_precedence(node.getToken()), context)
		if needsParens {
			this.add(")")
		}
	}
}

